using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class NurseNativeHairCandidate {
 static string Key(Vector3 p){return Mathf.RoundToInt(p.x*100000)+","+Mathf.RoundToInt(p.y*100000)+","+Mathf.RoundToInt(p.z*100000);}
 public static void Run(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var go=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/EntityStudioGenerated/RebirthNurseNative/RebirthNurse_Authoring.prefab"));var moe=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/NativeReferences/Moe/PrefabInstance/ZMoe.prefab"));go.GetComponent<Animator>().enabled=false;moe.GetComponent<Animator>().enabled=false;go.GetComponent<LODGroup>().ForceLOD(0);RebirthEntityStudio.RebirthNurseNativeShaderPreview.Bind(go);var r=go.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(x=>x.name=="LOD0");var donor=moe.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(x=>x.name=="LOD0");var source=NurseAnatomyRender.WorldSkin(donor);var indices=source.GetTriangles(1);var ids=indices.Distinct().OrderBy(i=>i).ToArray();var reindex=ids.Select((id,i)=>new{id,i}).ToDictionary(v=>v.id,v=>v.i);var points=source.vertices;var sourceNormals=source.normals;var sourceTangents=source.tangents;var sourceUV=source.uv;float top=ids.Max(i=>points[i].y),bottom=ids.Min(i=>points[i].y),width=ids.Max(i=>Mathf.Abs(points[i].x));var old=r.sharedMesh;var oldWorld=NurseAnatomyRender.WorldSkin(r).vertices;var oldWeights=old.boneWeights;var oldHair=old.GetTriangles(1).Distinct().ToArray();int head=Array.FindIndex(r.bones,b=>b.name=="Head");
 Func<Vector3,Vector3> map=p=>{float front=Mathf.SmoothStep(0,1,Mathf.InverseLerp(.015f,.065f,p.z))*(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(.045f,.085f,Mathf.Abs(p.x))));float f=(top-p.y)/Mathf.Max(.001f,top-bottom);return new Vector3(p.x*.122f/width,Mathf.Lerp(1.755f-f*.43f,1.755f-(top-p.y)*.86f,front),p.z*.92f);};
 var vertices=new Vector3[ids.Length];var normals=new Vector3[ids.Length];var tangents=new Vector4[ids.Length];var uv=new Vector2[ids.Length];var weights=new BoneWeight[ids.Length];float maxError=0;
 for(int k=0;k<ids.Length;k++){int i=ids[k];var desired=map(points[i]);int nearest=oldHair.OrderBy(j=>(oldWorld[j]-desired).sqrMagnitude).First();var w=desired.y>1.67f?new BoneWeight{boneIndex0=head,weight0=1}:oldWeights[nearest];weights[k]=w;int[] bones={w.boneIndex0,w.boneIndex1,w.boneIndex2,w.boneIndex3};float[] values={w.weight0,w.weight1,w.weight2,w.weight3};var skin=Matrix4x4.zero;for(int b=0;b<4;b++){var value=r.bones[bones[b]].localToWorldMatrix*old.bindposes[bones[b]];for(int row=0;row<4;row++)for(int col=0;col<4;col++)skin[row,col]+=value[row,col]*values[b];}vertices[k]=skin.inverse.MultiplyPoint3x4(desired);maxError=Mathf.Max(maxError,Vector3.Distance(skin.MultiplyPoint3x4(vertices[k]),desired));
 float h=.0001f;var jacobian=Matrix4x4.identity;for(int axis=0;axis<3;axis++){var offset=Vector3.zero;offset[axis]=h;var v=(map(points[i]+offset)-map(points[i]-offset))/(2*h);jacobian.SetColumn(axis,new Vector4(v.x,v.y,v.z,0));}var worldNormal=jacobian.inverse.transpose.MultiplyVector(sourceNormals[i]).normalized;normals[k]=skin.inverse.MultiplyVector(worldNormal).normalized;var st=sourceTangents[i];var tangent=skin.inverse.MultiplyVector(jacobian.MultiplyVector(new Vector3(st.x,st.y,st.z))).normalized;tangents[k]=new Vector4(tangent.x,tangent.y,tangent.z,st.w);uv[k]=sourceUV[i];}
 if(maxError>.00001f)throw new Exception("Native card bind conversion mismatch");var hairMesh=new Mesh{name="NativeMoeHairFittedCandidate",vertices=vertices,normals=normals,tangents=tangents,uv=uv,boneWeights=weights,bindposes=old.bindposes,triangles=indices.Select(i=>reindex[i]).ToArray()};hairMesh.RecalculateBounds();var body=UnityEngine.Object.Instantiate(old);var original=body.vertices;var smooth=(Vector3[])original.Clone();var hairSet=new HashSet<int>(old.GetTriangles(1));var pinned=new HashSet<int>(old.GetTriangles(0));var links=hairSet.ToDictionary(i=>i,i=>new HashSet<int>());var hi=old.GetTriangles(1);for(int j=0;j<hi.Length;j+=3)for(int a=0;a<3;a++)for(int b=0;b<3;b++)if(a!=b)links[hi[j+a]].Add(hi[j+b]);var groups=Enumerable.Range(0,original.Length).GroupBy(i=>Key(original[i])).Select(g=>g.ToArray()).ToArray();int moved=0;
 for(int step=0;step<12;step++){var next=(Vector3[])smooth.Clone();foreach(var group in groups){if(group.Any(i=>!hairSet.Contains(i)||pinned.Contains(i)))continue;int i=group[0];var wp=r.transform.TransformPoint(original[i]);if(wp.y>1.66f||wp.y<1.30f)continue;var neighbours=group.SelectMany(j=>links[j]).Distinct().ToArray();if(neighbours.Length<3)continue;var average=Vector3.zero;foreach(int j in neighbours)average+=smooth[j];average/=neighbours.Length;var v=Vector3.Lerp(smooth[i],average,.30f);v=original[i]+Vector3.ClampMagnitude(v-original[i],.008f);foreach(int j in group)next[j]=v;}smooth=next;}for(int i=0;i<smooth.Length;i++){if(pinned.Contains(i)&&smooth[i]!=original[i])throw new Exception("Body vertex moved");if(smooth[i]!=original[i])moved++;}body.vertices=smooth;body.RecalculateBounds();r.sharedMesh=body;var child=new GameObject("NativeHairCandidate");child.transform.SetParent(r.transform,false);var renderer=child.AddComponent<SkinnedMeshRenderer>();renderer.sharedMesh=hairMesh;renderer.bones=r.bones;renderer.rootBone=r.rootBone;renderer.updateWhenOffscreen=true;var material=new Material(AssetDatabase.LoadAssetAtPath<Material>("Assets/NativeReferences/Moe/Material/HD_MoeHair.mat"));material.shader=RebirthEntityStudio.RebirthNativeShaderLibrary.Get("Game/Autodesk");material.SetColor("_Color",new Color(8f,6.4f,4.5f,1));renderer.sharedMaterial=material;UnityEngine.Object.DestroyImmediate(moe);
 foreach(int angle in new[]{0,90,180,270}){go.transform.rotation=Quaternion.Euler(0,angle,0);NurseVisualOptimization.Render(go,"NativeLayerCandidate_Hair_"+angle,0,true,true);}File.WriteAllText(NurseVisualOptimization.Out+"/native-hair-fit-candidate.txt","Candidate only. Native Moe card triangles="+indices.Length/3+" vertices="+ids.Length+" source y="+bottom+".."+top+" halfwidth="+width+". Donor UVs/material/maps preserved; side/back length adapted, fringe kept short. Nurse rig reused; existing weights transferred with Head pinned roots; bind reconstruction max error="+maxError+". Old body submesh unchanged; complete hair foundation retained, hair-only contour smoothing bounded to 8mm. Source normals/tangents retained. Core moved vertices="+moved+". No prefab or installed asset writes. Requires visual review.");}
}
